//! PROTOTYPE, unverified, for measurement only (bench/ branch): an AVX2 4-way
//! Montgomery ladder for X25519, radix 2^25.5. Generated by proto_gen.py.
#![allow(clippy::all, unsafe_op_in_unsafe_fn, missing_docs)]

pub static CHOSEN: core::sync::atomic::AtomicBool = core::sync::atomic::AtomicBool::new(false);
const X1: usize = 64;
const X2: usize = 96;
const OFF: [u32; 10] = [0, 26, 51, 77, 102, 128, 153, 179, 204, 230];
const WID: [u32; 10] = [26, 25, 26, 25, 26, 25, 26, 25, 26, 25];

const fn p2(k: usize) -> u64 {
    if k == 0 { (1 << 27) - 38 } else if k % 2 == 0 { (1 << 27) - 2 } else { (1 << 26) - 2 }
}

fn pack(l: [u64; 10]) -> [u64; 4] {
    let mut w = [0u64; 5];
    for k in 0..10 {
        let v = (l[k] as u128) << (OFF[k] % 64);
        let i = (OFF[k] / 64) as usize;
        let (s, c) = w[i].overflowing_add(v as u64);
        w[i] = s;
        let mut carry = (v >> 64) as u64 + c as u64;
        let mut j = i + 1;
        while carry != 0 && j < 5 {
            let (s, c) = w[j].overflowing_add(carry);
            w[j] = s;
            carry = c as u64;
            j += 1;
        }
    }
    [w[0], w[1], w[2], w[3]]
}

unsafe fn put(ws: *mut u8, off: usize, v: [u64; 4]) {
    core::ptr::write_unaligned(ws.add(off) as *mut [u64; 4], v);
}

pub unsafe extern "sysv64" fn vg_proto_ladder_avx2(ws: *mut u8) {
    let x1w = core::ptr::read_unaligned(ws.add(X1) as *const [u64; 4]);
    let big = (x1w[0] as u128) | ((x1w[1] as u128) << 64);
    let big2 = (x1w[2] as u128) | ((x1w[3] as u128) << 64);
    let limb = |k: usize| -> u64 {
        let o = OFF[k];
        let v: u128 = if o < 128 {
            let lo = big >> o;
            if o == 0 { lo } else { lo | (big2 << (128 - o)) }
        } else {
            big2 >> (o - 128)
        };
        v as u64 & ((1u64 << WID[k]) - 1)
    };
    for k in 0..10 {
        let one = if k == 0 { 1 } else { 0 };
        put(ws, 1024 + 32 * k, [one, 0, limb(k), one]);
        put(ws, 1664 + 32 * k, [0, 0, one, limb(k)]);
        put(ws, 1344 + 32 * k, [0, p2(k) + 1, 0, p2(k) + 1]);
    }
    put(ws, 1984, [19; 4]);
    put(ws, 2016, [38; 4]);
    put(ws, 2048, [(1 << 26) - 1; 4]);
    put(ws, 2080, [(1 << 25) - 1; 4]);
    put(ws, 2112, [0, 121666, 0, 0]);
    put(ws, 2144, [0x0000000400000004; 4]);
    put(ws, 2176, [0x0000000100000000, 0x0000000300000002, 0x0000000700000006, 0x0000000500000004]);
    put(ws, 2208, [0x0000000100000000, 0x0000000300000002, 0x0000000100000000, 0x0000000300000002]);
    put(ws, 2240, [0, !0, 0, !0]);
    ladder_loop(ws);
    let mut l = [[0u64; 10]; 4];
    for k in 0..10 {
        let tmp = core::ptr::read_unaligned(ws.add(1024 + 32 * k) as *const [u64; 4]);
        for lane in 0..4 {
            l[lane][k] = tmp[lane];
        }
    }
    for lane in 0..4 {
        put(ws, X2 + 32 * lane, pack(l[lane]));
    }
}

